package dustin.cex.domains.kyc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.edd.*;
import dustin.cex.domains.security.OperatorMfaService;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.web.server.ResponseStatusException;

/** 실제 업무별 서명·변경 근거 재확인·경합·감사 실패의 원자성을 검증한다. */
class CustomerFinalApprovalIntegrationTest extends CustomerFinalTestSupport {
    @Test void actualSignedApprovalClosesReviewWithoutChangingFinancialEffects() throws Exception {var r=approvedFinal();assertEquals("APPROVED",r.status());assertEquals(1,active());blocked();assertEquals(List.of(reply),replies.own(customer.getId(),sid,receipt.id(),0));assertThrows(ResponseStatusException.class,this::draft);}
    @Test void rejectionRetainsHistoryAndAllowsNewDraft() throws Exception {var r=draft();assertEquals("REJECTED",finalDecide(r,false,finalProof(r,false)).status());assertNotNull(draft());assertEquals(1,active());}
    @Test void ownInspectionAndExactHashAreRequiredForOptions(){var r=draft();assertThrows(ResponseStatusException.class,()->finals.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));finals.inspect(checker.user().getId(),checker.sid(),r.payload().id());assertThrows(ResponseStatusException.class,()->finals.options(checker.user().getId(),checker.sid(),r.payload().id(),"0".repeat(64),true));}
    @Test void requesterAndUnassignedApproverCannotDecide() throws Exception {var r=draft();var proof=finalProof(r,true);for(var a:List.of(maker,independent,nextChecker))assertThrows(ResponseStatusException.class,()->finals.decide(a.user().getId(),a.sid(),r.payload().id(),r.payloadHash(),true,proof));assertEquals("APPROVED",finalDecide(r,true,proof).status());}
    @Test void oppositeDirectionProofCannotApprove() throws Exception {var r=draft();var proof=finalProof(r,false);assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));assertEquals("REJECTED",finalDecide(r,false,proof).status());}
    @Test void anotherBusinessProofCannotApproveFinalReply() throws Exception {var r=draft();var handoff=proposal(maker,UUID.randomUUID());var proof=handoffProof(independent,handoff,true);finals.inspect(checker.user().getId(),checker.sid(),r.payload().id());assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));assertEquals("APPROVED",finalDecide(r,true,finalProof(r,true)).status());}
    @Test void changedRequesterVersionInvalidatesExistingProof() throws Exception {var r=draft();var proof=finalProof(r,true);var u=users.findById(maker.user().getId()).orElseThrow();u.setUsername("작성자 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));}
    @Test void changedCheckerVersionInvalidatesExistingProof() throws Exception {var r=draft();var proof=finalProof(r,true);var u=users.findById(checker.user().getId()).orElseThrow();u.setUsername("검토자 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));}
    @Test void newNoteInvalidatesAlreadySignedProof() throws Exception {var r=draft();var proof=finalProof(r,true);notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"새 자료 재검토"));assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));}
    @Test void transferInvalidatesAlreadySignedProof() throws Exception {var r=draft();var proof=finalProof(r,true);transfer();assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));}
    @Test void actualRescissionInvalidatesAlreadySignedProof() throws Exception {var r=draft();var proof=finalProof(r,true);approveWithdrawal(withdraw(UUID.randomUUID()));assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));}
    @Test void decisionAuditFailureRestoresProofForSameRetry() throws Exception {var r=draft();var proof=finalProof(r,true);doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_FINAL_DECIDED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->finalDecide(r,true,proof));reset(audit);assertEquals("PENDING",finals.status(maker.user().getId(),maker.sid(),r.payload().id()).status());assertEquals("APPROVED",finalDecide(r,true,proof).status());}
    @Test void repeatedDecisionCannotConsumeAnotherFinalResult() throws Exception {var r=draft();var proof=finalProof(r,true);finalDecide(r,true,proof);assertThrows(ResponseStatusException.class,()->finalDecide(r,true,proof));assertEquals("APPROVED",finals.status(maker.user().getId(),maker.sid(),r.payload().id()).status());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_review_final_decisions WHERE review_id=?",Long.class,receipt.id()));}
    @Test void concurrentApprovalAndRejectionCommitOneDecision() throws Exception {var r=draft();var yes=finalProof(r,true);var no=finalProof(r,false);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var futures=List.of(pool.submit(()->race(start,()->finalDecide(r,true,yes))),pool.submit(()->race(start,()->finalDecide(r,false,no))));start.countDown();int successes=0;for(var f:futures)if(f.get(20,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_review_final_decisions WHERE request_id=?",Long.class,r.payload().id()));}finally{pool.shutdownNow();}}
    boolean race(CountDownLatch start,Runnable work) throws Exception {start.await();try{work.run();return true;}catch(ResponseStatusException e){return false;}}
    @Test void closedReviewRejectsNewNotesAndStatusReplies() throws Exception {approvedFinal();assertThrows(ResponseStatusException.class,()->notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"확정 이후 새 메모")));assertThrows(ResponseStatusException.class,()->replies.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),note.id()));}
    @Test void httpDecisionUsesActualProofAndNoStore() throws Exception {var r=draft();var proof=finalProof(r,true);mvc.perform(post("/api/admin/compliance/customer-final-requests/"+r.payload().id()+"/approve").header("Authorization","Bearer "+checker.access()).contentType("application/json").content(json.writeValueAsString(Map.of("payloadHash",r.payloadHash(),"proof",proof)))).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store")));assertEquals("APPROVED",finals.status(maker.user().getId(),maker.sid(),r.payload().id()).status());}
}
